{"path":"server.js","content":"import http from 'node:http';
import { readFileSync, writeFileSync, renameSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const defaultFile = join(root, 'data', 'books.json');

function send(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(data));
}

function loadBooks(file) {
  try {
    const books = JSON.parse(readFileSync(file, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function saveBooks(file, books) {
  mkdirSync(dirname(file), { recursive: true });
  const temp = `${file}.${randomUUID()}.tmp`;
  writeFileSync(temp, JSON.stringify(books, null, 2) + '\n');
  renameSync(temp, file);
}

async function readBody(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 100_000) throw new Error('Request too large');
  }
  try { return JSON.parse(text); } catch { throw new Error('Invalid JSON'); }
}

export function createApp({ file = defaultFile } = {}) {
  return http.createServer(async (req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost');
      const pathname = url.pathname;
      const bookId = pathname.match(/^\/api\/books\/([a-f0-9-]+)$/);
      if (req.method === 'GET' && pathname === '/api/books') {
        return send(res, 200, loadBooks(file));
      }
      if (req.method === 'GET' && bookId) {
        const book = loadBooks(file).find(item => item.id === bookId[1]);
        return send(res, book ? 200 : 404, book || { error: 'Book not found' });
      }
      if (req.method === 'POST' && pathname === '/api/books') {
        const input = await readBody(req);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        const author = typeof input?.author === 'string' ? input.author.trim() : '';
        const notes = typeof input?.notes === 'string' ? input.notes.trim() : '';
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
          return send(res, 400, { error: 'Enter a title and author (and keep notes under 10,000 characters).' });
        }
        const books = loadBooks(file);
        const book = { id: randomUUID(), title, author, notes, status: 'reading', addedAt: new Date().toISOString() };
        books.unshift(book);
        saveBooks(file, books);
        return send(res, 201, book);
      }
      if (req.method === 'PATCH' && bookId) {
        const input = await readBody(req);
        if (input?.status !== 'finished') return send(res, 400, { error: 'Invalid status' });
        const books = loadBooks(file);
        const book = books.find(item => item.id === bookId[1]);
        if (!book) return send(res, 404, { error: 'Book not found' });
        book.status = 'finished';
        book.finishedAt ||= new Date().toISOString();
        saveBooks(file, books);
        return send(res, 200, book);
      }
      if (req.method === 'GET' && (pathname === '/' || /^\/books\/[a-f0-9-]+$/.test(pathname))) {
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        return res.end(readFileSync(join(root, 'public', 'index.html')));
      }
      const asset = { '/app.js': ['app.js', 'text/javascript; charset=utf-8'], '/styles.css': ['styles.css', 'text/css; charset=utf-8'] }[pathname];
      if (req.method === 'GET' && asset) {
        res.writeHead(200, { 'Content-Type': asset[1] });
        return res.end(readFileSync(join(root, 'public', asset[0])));
      }
      return send(res, 404, { error: 'Not found' });
    } catch (error) {
      if (error.message === 'Invalid JSON' || error.message === 'Request too large') return send(res, 400, { error: error.message });
      console.error(error);
      return send(res, 500, { error: 'Unable to access books right now' });
    }
  });
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const port = Number(process.env.PORT || 3000);
  createApp({ file: process.env.BOOKS_FILE || defaultFile }).listen(port, () => {
    console.log(`Bookkeeping is running at http://localhost:${port}`);
  });
}
"}

