const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

async function api(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong');
  return data;
}

function bookCard(book, index) {
  return `<article class="book-card">
    <div class="book-spine spine-${index % 5}" aria-hidden="true"><span class="spine-decoration">✳</span><span class="spine-title">${escapeHTML(book.title)}</span><span class="spine-author">${escapeHTML(book.author)}</span></div>
    <div class="book-info"><span class="eyebrow">${book.status === 'finished' ? 'Finished' : 'Currently reading'}</span><h3><a href="/books/${book.id}">${escapeHTML(book.title)}</a></h3><p class="book-author">by ${escapeHTML(book.author)}</p>
    <div class="card-actions"><a class="text-link" href="/books/${book.id}">View book <span aria-hidden="true">↗</span></a>${book.status === 'reading' ? `<button class="finish-link" type="button" data-finish="${book.id}">Mark finished <span aria-hidden="true">✓</span></button>` : ''}</div></div>
  </article>`;
}

function emptyShelf(label, message) {
  return `<div class="empty-shelf"><span aria-hidden="true" class="empty-icon">✳</span><p>${label}</p><span>${message}</span></div>`;
}

async function renderHome() {
  document.title = 'Between the Lines — Your reading shelf';
  app.innerHTML = `<div class="loading">Opening your shelf…</div>`;
  try {
    const books = await api('/api/books');
    const reading = books.filter(book => book.status === 'reading');
    const finished = books.filter(book => book.status === 'finished');
    app.innerHTML = `<div class="page-shell">
      <section class="hero"><div class="hero-copy"><span class="eyebrow hero-eyebrow"><span class="little-star">✳</span> YOUR PERSONAL READING SHELF</span><h1>Every book has<br><em>a story.</em> <span>Here's yours.</span></h1><p>A cozy corner to keep track of what you're reading, remember what you loved, and see how far you've come.</p><a href="#add-book" class="primary-button">Add a book <span aria-hidden="true">↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-spark spark-one">✳</div><div class="art-spark spark-two">✦</div><div class="art-book book-back"></div><div class="art-book book-middle"></div><div class="art-book book-front"><span>the<br>next<br>chapter</span><i>✳</i></div><div class="art-caption">A good book is always a good idea.</div></div></section>
      <div class="content-grid"><div class="shelf-column"><div class="shelf-intro"><span class="eyebrow">THE COLLECTION</span><h2>Your bookshelf<span class="heading-dot">.</span></h2><p>All your reads, right where you left them.</p></div>
      <section class="shelf-section" aria-labelledby="reading-title"><div class="section-heading"><div><span class="section-mark mark-reading"></span><h2 id="reading-title">Currently reading</h2><span class="count">${reading.length}</span></div><span class="section-aside">The stories unfolding</span></div><div class="book-list">${reading.length ? reading.map(bookCard).join('') : emptyShelf('A fresh chapter awaits', 'Add a book to get your shelf started.')}</div></section>
      <section class="shelf-section finished-section" aria-labelledby="finished-title"><div class="section-heading"><div><span class="section-mark mark-finished"></span><h2 id="finished-title">Finished books</h2><span class="count">${finished.length}</span></div><span class="section-aside">The ones that stayed with you</span></div><div class="book-list">${finished.length ? finished.map((book, index) => bookCard(book, index + reading.length)).join('') : emptyShelf('Nothing here just yet', 'Finished books will find their home here.')}</div></section></div>
      <aside class="aside-column"><div class="form-panel" id="add-book"><span class="form-symbol" aria-hidden="true">✳</span><span class="eyebrow">GROW YOUR SHELF</span><h2>Add a new book<span class="heading-dot">.</span></h2><p>What are you diving into next?</p><form id="book-form"><label for="title">Book title</label><input id="title" name="title" type="text" placeholder="e.g. The Midnight Library" maxlength="200" required /><label for="author">Author</label><input id="author" name="author" type="text" placeholder="e.g. Matt Haig" maxlength="200" required /><label for="notes">Your notes <span>(optional)</span></label><textarea id="notes" name="notes" rows="5" maxlength="10000" placeholder="A thought, a quote, a reason you picked it up…"></textarea><div id="form-error" class="form-error" role="alert" hidden></div><button class="submit-button" type="submit">Add to my shelf <span aria-hidden="true">↗</span></button></form></div><div class="aside-note"><span aria-hidden="true">“</span><p>There is no friend as loyal as a book.</p><small>— Ernest Hemingway</small></div></aside></div></div>`;
    document.querySelector('#book-form').addEventListener('submit', async event => {
      event.preventDefault();
      const form = event.currentTarget;
      const button = form.querySelector('button[type="submit"]');
      const error = form.querySelector('#form-error');
      error.hidden = true;
      button.disabled = true;
      try {
        const book = await api('/api/books', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(new FormData(form))) });
        window.location.href = `/books/${book.id}`;
      } catch (err) { error.textContent = err.message; error.hidden = false; button.disabled = false; }
    });
    document.querySelectorAll('[data-finish]').forEach(button => button.addEventListener('click', () => finishBook(button.dataset.finish, button)));
  } catch (err) { showError(err); }
}

async function finishBook(id, button) {
  button.disabled = true;
  try {
    await api(`/api/books/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }) });
    await renderHome();
  } catch (err) { button.disabled = false; alert(err.message); }
}

async function renderBook(id) {
  app.innerHTML = `<div class="loading">Opening your book…</div>`;
  try {
    const book = await api(`/api/books/${id}`);
    document.title = `${book.title} — Between the Lines`;
    app.innerHTML = `<div class="page-shell detail-shell"><a class="back-link" href="/"><span aria-hidden="true">←</span> Back to bookshelf</a><div class="detail-grid"><div class="detail-cover-wrap"><div class="detail-cover"><span class="cover-ornament">✳</span><span class="cover-title">${escapeHTML(book.title)}</span><span class="cover-line"></span><span class="cover-author">${escapeHTML(book.author)}</span></div><span class="cover-undertext">A book worth remembering <span aria-hidden="true">✳</span></span></div><div class="detail-content"><span class="eyebrow"><span class="status-indicator"></span>${book.status === 'finished' ? 'FINISHED BOOK' : 'CURRENTLY READING'}</span><h1>${escapeHTML(book.title)}</h1><p class="detail-author">by ${escapeHTML(book.author)}</p><div class="detail-rule"></div><div class="notes-heading"><span class="eyebrow">FROM THE MARGINS</span><h2>Your notes<span class="heading-dot">.</span></h2></div><div class="notes-content">${book.notes ? escapeHTML(book.notes) : '<span class="no-notes">No notes for this one yet.</span>'}</div><div class="detail-actions"><button id="share-button" type="button" class="outline-button">Copy book link <span aria-hidden="true">↗</span></button>${book.status === 'reading' ? '<button id="finish-button" type="button" class="detail-finish">Mark as finished <span aria-hidden="true">✓</span></button>' : '<span class="finished-badge">✓ &nbsp; Finished</span>'}</div><p id="action-message" class="action-message" role="status"></p></div></div></div>`;
    document.querySelector('#share-button').addEventListener('click', async () => {
      const message = document.querySelector('#action-message');
      try {
        await navigator.clipboard.writeText(window.location.href);
        message.textContent = 'Link copied! Ready to share.';
      } catch { message.textContent = `Share this link: ${window.location.href}`; }
    });
    document.querySelector('#finish-button')?.addEventListener('click', async event => {
      const button = event.currentTarget;
      button.disabled = true;
      try {
        await api(`/api/books/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }) });
        await renderBook(id);
      } catch (err) { document.querySelector('#action-message').textContent = err.message; button.disabled = false; }
    });
  } catch (err) {
    if (err.message === 'Book not found') {
      document.title = 'Book not found — Between the Lines';
      app.innerHTML = `<div class="not-found"><span aria-hidden="true">✳</span><h1>That book isn't on the shelf.</h1><p>The link may be wrong, or this book no longer exists.</p><a class="primary-button" href="/">Back to bookshelf <span aria-hidden="true">↗</span></a></div>`;
    } else showError(err);
  }
}

function showError(err) {
  app.innerHTML = `<div class="not-found"><span aria-hidden="true">✳</span><h1>We couldn't open your shelf.</h1><p>${escapeHTML(err.message)}</p><a class="primary-button" href="/">Try again <span aria-hidden="true">↗</span></a></div>`;
}

const match = window.location.pathname.match(/^\/books\/([a-f0-9-]+)$/);
if (match) renderBook(match[1]); else renderHome();
"}

