        const book = await api('/api/books', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(new FormData(form))) });
        window.location.href = `/books/${book.id}`;
      } catch (err) { error.textContent = err.message; error.hidden = false; button.disabled = false; }
    });
    document.querySelectorAll('[data-finish]').forEach(button => button.addEventListener('click', () => finishBook(button.dataset.finish, button)));
  } catch (err) { showError(err); }
}

async function finishBook(id, button) {
  button.disabled = true;
  try {
    await api(`/api/books/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }) });
    await renderHome();
  } catch (err) { button.disabled = false; alert(err.message); }
}

async function renderBook(id) {
  app.innerHTML = `<div class="loading">Opening your book…</div>`;
  try {
    const book = await api(`/api/books/${id}`);
    document.title = `${book.title} — Between the Lines`;
    app.innerHTML = `<div class="page-shell detail-shell"><a class="back-link" href="/"><span aria-hidden="true">←</span> Back to bookshelf</a><div class="detail-grid"><div class="detail-cover-wrap"><div class="detail-cover"><span class="cover-ornament">✳</span><span class="cover-title">${escapeHTML(book.title)}</span><span class="cover-line"></span><span class="cover-author">${escapeHTML(book.author)}</span></div><span class="cover-undertext">A book worth remembering <span aria-hidden="true">✳</span></span></div><div class="detail-content"><span class="eyebrow"><span class="status-indicator"></span>${book.status === 'finished' ? 'FINISHED BOOK' : 'CURRENTLY READING'}</span><h1>${escapeHTML(book.title)}</h1><p class="detail-author">by ${escapeHTML(book.author)}</p><div class="detail-rule"></div><div class="notes-heading"><span class="eyebrow">FROM THE MARGINS</span><h2>Your notes<span class="heading-dot">.</span></h2></div><div class="notes-content">${book.notes ? escapeHTML(book.notes) : '<span class="no-notes">No notes for this one yet.</span>'}</div><div class="detail-actions"><button id="share-button" type="button" class="outline-button">Copy book link <span aria-hidden="true">↗</span></button>${book.status === 'reading' ? '<button id="finish-button" type="button" class="detail-finish">Mark as finished <span aria-hidden="true">✓</span></button>' : '<span class="finished-badge">✓ &nbsp; Finished</span>'}</div><p id="action-message" class="action-message" role="status"></p></div></div></div>`;
    document.querySelector('#share-button').addEventListener('click', async () => {
      const message = document.querySelector('#action-message');
      try {
        await navigator.clipboard.writeText(window.location.href);
        message.textContent = 'Link copied! Ready to share.';
      } catch { message.textContent = `Share this link: ${window.location.href}`; }
    });
    document.querySelector('#finish-button')?.addEventListener('click', async event => {
      const button = event.currentTarget;
      button.disabled = true;
      try {
        await api(`/api/books/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }) });
        await renderBook(id);
      } catch (err) { document.querySelector('#action-message').textContent = err.message; button.disabled = false; }
    });
  } catch (err) {
    if (err.message === 'Book not found') {
      document.title = 'Book not found — Between the Lines';
      app.innerHTML = `<div class="not-found"><span aria-hidden="true">✳</span><h1>That book isn't on the shelf.</h1><p>The link may be wrong, or this book no longer exists.</p><a class="primary-button" href="/">Back to bookshelf <span aria-hidden="true">↗</span></a></div>`;
    } else showError(err);
  }
}

function showError(err) {
  app.innerHTML = `<div class="not-found"><span aria-hidden="true">✳</span><h1>We couldn't open your shelf.</h1><p>${escapeHTML(err.message)}</p><a class="primary-button" href="/">Try again <span aria-hidden="true">↗</span></a></div>`;
}

const match = window.location.pathname.match(/^\/books\/([a-f0-9-]+)$/);
if (match) renderBook(match[1]); else renderHome();
